from sys import stdin, stdout
read = stdin.readline
t = int(read())
for testcase in range(t):
	(n, m) = map(int, read().split())
	scorearr = [list(map(int, read().split())) for i in range(n)]
	sumarr = [sum(i) for i in scorearr]
	cm = 0
	for i in range(m):
		cur = 0
		for j in range(n):
			temp = sumarr[j] - m * scorearr[j][i]
			if temp > 0:
				cur += temp
		if cur > cm:
			cm = cur
	for i in range(m):
		cur = 0
		for j in range(n):
			temp = m * scorearr[j][i] - sumarr[j]
			if temp > 0:
				cur += temp
		if cur > cm:
			cm = cur
	print(cm)
